// --- _shared/engine/classify.ts ---
// =====================================================================
// ResolveAI engine — deterministic understanding + ticket router
// Pure TS. Used as the primary classification path and as the fallback
// when the LLM is unavailable. Fuses LLM output when provided.
// =====================================================================

const BILLING_WORDS = [
  "charge", "charged", "twice", "double", "refund", "payment", "pay",
  "debit", "invoice", "billing", "money", "credit", "failed payment",
  "extra charge", "deducted",
];
const ORDER_WORDS = [
  "order", "delivery", "delivered", "shipped", "ship", "package", "parcel",
  "courier", "tracking", "return", "cancel", "cancelled", "missing",
  "received", "arrive", "deliver",
];
const TECHNICAL_WORDS = [
  "not working", "broken", "defect", "fault", "error", "app", "connect",
  "pairing", "sound", "battery", "charging", "display", "warranty", "repair",
];
const ACCOUNT_WORDS = [
  "login", "password", "account", "subscription", "renew", "sign in",
  "profile", "otp", "logged out", "subscription renewed",
];

const SUB_INTENT_MAP: [RegExp, string][] = [
  [/twice|double|duplicate|charged twice|debited twice/i, "duplicate_charge"],
  [/refund|money back|credit back/i, "refund"],
  [/never received|not received|missing package|not received my package/i, "missing_package"],
  [/deliver|courier|tracking|parcel|package/i, "delivery"],
  [/late|delay|delayed|not arrived/i, "late_delivery"],
  [/return/i, "return"],
  [/cancel|cancelled/i, "cancellation"],
  [/damaged|broken|defective|not working|fault/i, "damaged_item"],
  [/login|password|sign in|logged out|otp/i, "login"],
  [/subscription|renew/i, "subscription"],
  [/tracking/i, "tracking"],
  [/wrong (size|item|product)|received wrong/i, "wrong_item"],
  [/connect|pairing|bluetooth|earbuds|battery/i, "technical_failure"],
  [/invoice|charged extra|shipping charge/i, "shipping_charge"],
];

const NEGATIVE_WORDS = [
  "never", "not", "refused", "failed", "wrong", "missing", "charged", "twice",
  "damaged", "broken", "frustrated", "disappointed", "still", "again", "unhappy",
  "worst", "terrible", "poor",
];
const POSITIVE_WORDS = ["thanks", "thank you", "great", "good", "excellent", "happy", "pleased"];
const URGENT_WORDS = [
  "urgent", "twice", "already", "contacted", "immediately", "still", "not received",
  "never", "asap", "frustrated", "second time", "third time", "refund", "money",
];

function countMatches(text: string, words: string[]): number {
  const lower = text.toLowerCase();
  return words.reduce((n, w) => (lower.includes(w.toLowerCase()) ? n + 1 : n), 0);
}

function detectIntent(message: string): { intent: string; score: number } {
  const scores = {
    billing: countMatches(message, BILLING_WORDS),
    order: countMatches(message, ORDER_WORDS),
    technical: countMatches(message, TECHNICAL_WORDS),
    account: countMatches(message, ACCOUNT_WORDS),
  };
  const best = Object.entries(scores).sort((a, b) => b[1] - a[1])[0];
  return { intent: best[0], score: best[1] };
}

function detectSubIntents(message: string): string[] {
  const found: string[] = [];
  for (const [re, sub] of SUB_INTENT_MAP) {
    if (re.test(message)) found.push(sub);
  }
  return found.length > 0 ? found : ["general"];
}

function detectSentiment(message: string): {
  sentiment: Understanding["sentiment"];
  sentimentScore: number;
} {
  let neg = countMatches(message, NEGATIVE_WORDS);
  const pos = countMatches(message, POSITIVE_WORDS);
  // Strong complaint phrases count as extra negative signals.
  const phraseHits = [
    /never received/i,
    /not received/i,
    /never got/i,
    /didn'?t receive/i,
    /keeps failing/i,
    /refund.*not|not.*refund/i,
    /still (pending|failing|nothing)/i,
  ].reduce((n, re) => (re.test(message) ? n + 1 : n), 0);
  neg += phraseHits;
  const score = Math.min(1, Math.max(0, 0.55 + pos * 0.15 - neg * 0.12));
  return {
    sentiment: score >= 0.6 ? "positive" : score >= 0.4 ? "neutral" : "negative",
    sentimentScore: Number(score.toFixed(2)),
  };
}

function detectUrgency(message: string, intent: string): Understanding["urgency"] {
  const urgentHits = countMatches(message, URGENT_WORDS);
  if (urgentHits >= 3) return "high";
  if (urgentHits >= 1) return "medium";
  return "low";
}

function computePriority(urgency: string, sentiment: string): string {
  if (urgency === "high") return sentiment === "negative" ? "P1" : "P2";
  if (urgency === "medium") return sentiment === "negative" ? "P2" : "P3";
  return "P4";
}

const ROUTING_REASON: Record<string, string> = {
  billing: "Payment discrepancy detected",
  order: "Order / delivery issue detected",
  technical: "Product or technical issue detected",
  account: "Account-related issue detected",
};

/** Deterministic understanding of a customer message. */
export function classifyMessage(
  message: string,
  customerRepeatContacts = 0,
): Omit<Understanding, "specialist"> & { intentScore: number } {
  const intent = detectIntent(message);
  const subIntents = detectSubIntents(message);
  const senti = detectSentiment(message);
  const urgency = detectUrgency(message, intent.intent);
  const priority = computePriority(urgency, senti.sentiment);

  // Base confidence from keyword signal strength, adjusted for ambiguity.
  let confidence = 0.68 + Math.min(0.25, intent.score * 0.08);
  if (intent.score === 0) confidence = 0.45;
  if (customerRepeatContacts >= 2) confidence = Math.min(0.98, confidence + 0.04);

  return {
    intent: intent.intent,
    intentScore: intent.score,
    subIntents,
    urgency,
    sentiment: senti.sentiment,
    sentimentScore: senti.sentimentScore,
    priority,
    confidence: Number(confidence.toFixed(2)),
    routingReason: ROUTING_REASON[intent.intent] ?? "Generic support request",
  };
}

export interface RouterInput {
  message: string;
  customerRepeatContacts: number;
  llmUnderstanding?: Partial<Understanding> | null;
}

/** Ticket router: fuse deterministic classification with optional LLM output. */
export function routeTicket(input: RouterInput): Understanding {
  const det = classifyMessage(input.message, input.customerRepeatContacts);
  const llm = input.llmUnderstanding;

  // The deterministic classifier is the source of truth when its keyword
  // signal is strong (>= 2 hits). The LLM only decides when the message is
  // genuinely ambiguous (0 hits) or weakly signalled (1 hit) with high
  // LLM confidence. This prevents LLM drift from misrouting clear cases.
  const validLlm = llm?.intent && ["billing", "order", "technical", "account"].includes(llm.intent);
  const llmCanDecide = det.intentScore === 0 ||
    (det.intentScore === 1 && (llm?.confidence ?? 0) >= 0.75);

  const intent = validLlm && llmCanDecide ? llm.intent : det.intent;
  const subIntents = validLlm && llmCanDecide && llm?.subIntents?.length
    ? llm.subIntents.slice(0, 4)
    : det.subIntents;
  const urgency = (validLlm && llmCanDecide && llm?.urgency) ?? det.urgency;
  const sentiment = (validLlm && llmCanDecide && llm?.sentiment) ?? det.sentiment;
  const confidence = llm?.confidence != null && llmCanDecide
    ? Math.max(0.5, Math.min(0.99, llm.confidence))
    : det.confidence;

  const specialistByIntent: Record<string, string> = {
    billing: "billing", order: "order", technical: "technical", account: "account",
  };

  return {
    intent,
    subIntents,
    urgency,
    sentiment,
    sentimentScore: (validLlm && llmCanDecide && llm?.sentimentScore) ?? det.sentimentScore,
    priority: (validLlm && llmCanDecide && llm?.priority) ?? computePriority(urgency, sentiment),
    confidence,
    specialist: specialistByIntent[intent] ?? "order",
    routingReason: (validLlm && llmCanDecide && llm?.routingReason) ?? ROUTING_REASON[intent] ?? "Specialist match",
  };
}

/** Simple rule fallback for generating a customer response when the LLM is down. */
export function fallbackResponse(
  resolved: boolean,
  ctx: {
    customerName: string;
    intent: string;
    rootCause?: string | null;
    contradiction?: boolean;
    refundIssued?: boolean;
    escalated?: boolean;
  },
): string {
  const { customerName, intent } = ctx;
  if (ctx.contradiction) {
    return `Hi ${customerName}, we take this very seriously. Our systems flagged a discrepancy between the courier's delivery record and the GPS proof of delivery. Because of the conflicting evidence, our team has taken over the case to investigate personally. You will receive an update shortly.`;
  }
  if (ctx.escalated) {
    return `Hi ${customerName}, I'm sorry for the trouble. This case needs specialist review, so I've escalated it to our ${intent} support team with all the details. You'll hear from us shortly.`;
  }
  if (resolved && ctx.refundIssued) {
    return `Hi ${customerName}, I've verified the duplicate charge on your order and issued a refund of ₹2,499 to your original payment method. It should reflect within 5-7 business days. We've also flagged your order for correction. Thank you for your patience.`;
  }
  if (resolved) {
    return `Hi ${customerName}, your issue has been resolved. ${ctx.rootCause ? "Root cause: " + ctx.rootCause + ". " : ""}Let us know if you need anything else.`;
  }
  return `Hi ${customerName}, we're looking into your ${intent} issue. Our team will update you shortly.`;
}

// --- _shared/engine/effort.ts ---
// =====================================================================
// ResolveAI engine — Customer Effort Score (pure TS)
// Computed from actual case records; never hardcoded.
// Higher score = more effort the customer had to expend.
// =====================================================================
export interface EffortInputs {
  contacts: number; // support contacts (tickets + cases)
  transfers: number; // escalations / queue transfers
  infoRequests: number; // inferred from messages asking for status/update
  resolutionHours: number; // time between first contact and resolution
  failedActions: number; // failed automated actions on the case
  escalations: number; // escalation count
}

export interface EffortResult {
  score: number; // 1 (low effort) .. 5 (high effort)
  label: "LOW" | "MODERATE" | "HIGH" | "VERY HIGH";
  factors: { name: string; weight: number; detail: string }[];
}

export function computeCustomerEffort(inputs: EffortInputs): EffortResult {
  const factors: EffortResult["factors"] = [];

  // Contacts: baseline 1 contact is expected; more = more effort.
  const contactFactor = Math.max(0, inputs.contacts - 1);
  factors.push({
    name: "Repeat contacts",
    weight: Math.min(1.0, contactFactor * 0.4),
    detail: `${inputs.contacts} contact(s)`,
  });

  const transferFactor = inputs.transfers + inputs.escalations;
  factors.push({
    name: "Transfers / escalations",
    weight: Math.min(1.0, transferFactor * 0.5),
    detail: `${transferFactor} transfer(s)/escalation(s)`,
  });

  const hoursFactor = Math.max(0, inputs.resolutionHours - 2);
  factors.push({
    name: "Resolution time",
    weight: Math.min(1.0, hoursFactor / 48),
    detail: `${Math.round(inputs.resolutionHours)}h to resolve`,
  });

  const failedFactor = inputs.failedActions;
  factors.push({
    name: "Failed actions",
    weight: Math.min(1.0, failedFactor * 0.6),
    detail: `${failedFactor} failed automated action(s)`,
  });

  const infoFactor = inputs.infoRequests;
  factors.push({
    name: "Status follow-ups",
    weight: Math.min(0.6, infoFactor * 0.2),
    detail: `${infoFactor} status inquiry(ies)`,
  });

  const totalWeight = factors.reduce((n, f) => n + f.weight, 0);
  // Score 1..5
  const score = Math.round((1 + Math.min(4, totalWeight)) * 10) / 10;

  return {
    score,
    label: score <= 1.6 ? "LOW" : score <= 2.6 ? "MODERATE" : score <= 3.6 ? "HIGH" : "VERY HIGH",
    factors,
  };
}

// --- _shared/engine/escalation.ts ---
// =====================================================================
// ResolveAI engine — escalation scoring
// Pure TS. Computes escalation_score + reasons + recommended queue.
// =====================================================================

export interface EscalationInputs {
  intent: string;
  caseComplexity: number; // 0..1
  repeatContacts: number;
  sentiment: string;
  financialImpact: number; // ₹
  policyUncertainty: boolean;
  conflictingEvidence: boolean;
  aiConfidence: number; // 0..1
  actionFailures: number;
  slaRisk: boolean; // SLA deadline at risk
}

const QUEUE_BY_INTENT: Record<string, string> = {
  billing: "Tier-2 Billing Investigations",
  order: "Tier-2 Order Investigations",
  technical: "Technical Support Team",
  account: "Account Review",
};

export function computeEscalation(
  inputs: EscalationInputs,
  confidenceFloor = 0.6,
): EscalationResult {
  let score = 0;
  const reasons: string[] = [];

  if (inputs.repeatContacts >= 2) {
    score += 15;
    reasons.push(`${inputs.repeatContacts} previous contacts for the same issue`);
  } else if (inputs.repeatContacts === 1) {
    score += 6;
  }

  if (inputs.conflictingEvidence) {
    score += 20;
    reasons.push("Contradictory evidence detected");
  }

  if (inputs.actionFailures >= 3) {
    score += 20;
    reasons.push("Automated action failed repeatedly");
  } else if (inputs.actionFailures > 0) {
    score += inputs.actionFailures * 5;
    reasons.push(`${inputs.actionFailures} failed automated action(s)`);
  }

  if (inputs.aiConfidence < confidenceFloor) {
    score += 15;
    reasons.push(`AI confidence below safe threshold (${Math.round(inputs.aiConfidence * 100)}%)`);
  }

  if (inputs.policyUncertainty) {
    score += 10;
    reasons.push("Policy uncertainty");
  }

  const financialWeight = Math.min(15, (inputs.financialImpact / 5000) * 8);
  score += financialWeight;
  if (inputs.financialImpact > 5000) reasons.push(`High financial impact (₹${inputs.financialImpact})`);

  if (inputs.sentiment === "negative") {
    score += 6;
    reasons.push("Customer frustration (negative sentiment)");
  }

  if (inputs.caseComplexity > 0.6) {
    score += 8;
    reasons.push("High case complexity");
  }

  if (inputs.slaRisk) {
    score += 5;
    reasons.push("SLA deadline at risk");
  }

  score = Math.min(100, Math.round(score));
  if (score === 0) reasons.push("No escalation triggers detected");

  return {
    score,
    reasons: [...new Set(reasons)].slice(0, 6),
    recommendedQueue: QUEUE_BY_INTENT[inputs.intent] ?? "General Support",
    priority: score >= 80 ? "P1" : score >= 55 ? "P2" : "P3",
  };
}

// --- _shared/engine/gates.ts ---
// =====================================================================
// ResolveAI engine — Four-Gate Controller (Evidence / Policy / Authority / Risk)
// Deterministic. The LLM proposes; these gates decide whether execution
// is permitted.
// =====================================================================

export interface GateInputs {
  evidence: EvidenceItem[];
  action: string;
  amount: number | null;
  customerTier: string;
  staffRole?: string | null;
  policyAllowed: boolean;
  policyId?: string | null;
  contradictions: number;
  repeatContacts: number;
  sentiment: string;
  uncertainty: number; // 0..1 (evidence gaps)
  highValueCustomer: boolean;
  hasDuplicates: boolean;
  actionFailures: number;
}

export function evaluateEvidenceGate(
  inputs: Pick<GateInputs, "evidence" | "uncertainty" | "hasDuplicates">,
): GateResult {
  const sourceCount = new Set(inputs.evidence.map((e) => e.source)).size;
  const factCount = inputs.evidence.filter((e) => e.known).length;
  const checks = [
    {
      name: "factual_evidence",
      pass: factCount >= 2,
      detail: `${factCount} factual evidence item(s) collected`,
    },
    {
      name: "independent_sources",
      pass: sourceCount >= 2,
      detail: `${sourceCount} independent source(s)`,
    },
    {
      name: "uncertainty_bounded",
      pass: inputs.uncertainty <= 0.4,
      detail: `uncertainty ${Math.round(inputs.uncertainty * 100)}%`,
    },
  ];
  const pass = checks.every((c) => c.pass);
  return {
    name: "GATE-1 Evidence",
    status: pass ? "PASS" : "FAIL",
    detail: pass
      ? "Sufficient factual evidence from independent sources."
      : "Insufficient evidence to support autonomous action.",
    checks,
  };
}

export function evaluatePolicyGate(
  inputs: Pick<GateInputs, "policyAllowed" | "policyId" | "action" | "contradictions">,
): GateResult {
  const checks = [
    {
      name: "action_permitted_by_policy",
      pass: inputs.policyAllowed,
      detail: `policy ${inputs.policyId ?? "none"} ${inputs.policyAllowed ? "permits" : "does not permit"} '${inputs.action}'`,
    },
    {
      name: "no_policy_violation",
      pass: inputs.contradictions === 0,
      detail:
        inputs.contradictions > 0
          ? `${inputs.contradictions} contradiction(s) detected — policy blocks auto-resolution`
          : "no contradictory evidence",
    },
  ];
  const pass = checks.every((c) => c.pass);
  return {
    name: "GATE-2 Policy",
    status: pass ? "PASS" : "FAIL",
    detail: pass
      ? "Company policy permits this action."
      : "Action is not permitted by applicable policy.",
    checks,
  };
}

export function evaluateAuthorityGate(
  inputs: Pick<GateInputs, "action" | "amount" | "customerTier" | "staffRole">,
): GateResult {
  const isMonetary = inputs.action === "issue_refund" || inputs.action === "cancel_order";
  const checks: { name: string; pass: boolean; detail: string }[] = [];

  if (!isMonetary || inputs.amount == null) {
    checks.push({
      name: "monetary_authority",
      pass: true,
      detail: "action requires no monetary authority",
    });
  } else {
    const actor = inputs.staffRole ?? inputs.customerTier;
    const limit = AUTHORITY_LIMITS[actor] ?? AUTHORITY_LIMITS.standard;
    const within = inputs.amount <= limit;
    checks.push({
      name: "amount_within_authority",
      pass: within,
      detail: `₹${inputs.amount} vs authority limit ₹${limit} for '${actor}'`,
    });
    checks.push({
      name: "actor_authorized",
      pass: Boolean(actor),
      detail: `acting authority: ${actor ?? "none"}`,
    });
  }

  const pass = checks.every((c) => c.pass);
  return {
    name: "GATE-3 Authority",
    status: pass ? "PASS" : "FAIL",
    detail: pass ? "Action is within the current authority limits." : "Action exceeds the current authority limit.",
    checks,
  };
}

export function evaluateRiskGate(
  inputs: Pick<
    GateInputs,
    | "amount"
    | "contradictions"
    | "repeatContacts"
    | "sentiment"
    | "uncertainty"
    | "highValueCustomer"
    | "actionFailures"
  >,
): GateResult {
  let score = 0;
  const checks: { name: string; pass: boolean; detail: string }[] = [];

  const fraudRisk = inputs.contradictions > 0 ? 0.85 : 0.05;
  checks.push({
    name: "fraud_risk",
    pass: fraudRisk < 0.5,
    detail: `fraud risk ${Math.round(fraudRisk * 100)}% (${inputs.contradictions > 0 ? "contradictory evidence" : "no signals"})`,
  });
  score += fraudRisk * 0.3;

  const financialRisk = inputs.amount ? Math.min(0.8, inputs.amount / 50000) : 0;
  checks.push({
    name: "financial_risk",
    pass: financialRisk < 0.5,
    detail: `financial exposure ₹${inputs.amount ?? 0}`,
  });
  score += financialRisk * 0.25;

  const customerRisk = Math.min(1, inputs.repeatContacts / 5) * 0.4 +
    (inputs.sentiment === "negative" ? 0.25 : 0);
  checks.push({
    name: "customer_risk",
    pass: customerRisk < 0.5,
    detail: `repeat contacts ${inputs.repeatContacts}, sentiment ${inputs.sentiment}`,
  });
  score += customerRisk * 0.2;

  checks.push({
    name: "uncertainty",
    pass: inputs.uncertainty <= 0.4,
    detail: `uncertainty ${Math.round(inputs.uncertainty * 100)}%`,
  });
  score += inputs.uncertainty * 0.15;

  const actionFailRisk = Math.min(1, inputs.actionFailures / 3);
  checks.push({
    name: "action_reliability",
    pass: actionFailRisk < 0.9,
    detail: `${inputs.actionFailures} prior action failure(s)`,
  });
  score += actionFailRisk * 0.1;

  score = Number(score.toFixed(2));
  const status = score >= 0.7 ? "BLOCK" : score >= 0.4 ? "REVIEW" : "PASS";
  return {
    name: "GATE-4 Risk",
    status,
    detail:
      status === "PASS"
        ? "Risk within acceptable bounds."
        : status === "REVIEW"
          ? "Elevated risk — human review required."
          : "High risk — action blocked.",
    checks,
  };
}

export interface FourGateSummary {
  gates: Record<string, GateResult>;
  allPass: boolean;
  canAutoResolve: boolean;
}

export function evaluateAllGates(inputs: GateInputs): FourGateSummary {
  const evidence = evaluateEvidenceGate(inputs);
  const policy = evaluatePolicyGate(inputs);
  const authority = evaluateAuthorityGate(inputs);
  const risk = evaluateRiskGate(inputs);

  const gates: Record<string, GateResult> = {
    evidence,
    policy,
    authority,
    risk,
  };
  const allPass = Object.values(gates).every((g) => g.status === "PASS");
  return { gates, allPass, canAutoResolve: allPass };
}

// --- _shared/engine/passport.ts ---
// =====================================================================
// ResolveAI engine — Resolution Passport builder
// Pure TS. Assembles the complete context handed to a human agent.
// =====================================================================

export function buildPassport(ctx: CaseContext): Record<string, unknown> {
  return {
    case_id: ctx.caseId,
    generated_at: new Date().toISOString(),
    customer: ctx.customer,
    original_complaint: ctx.message,
    understanding: {
      intent: ctx.intent,
      sub_intents: ctx.subIntents,
      urgency: ctx.urgency,
      sentiment: ctx.sentiment,
      confidence: ctx.routingConfidence,
      specialist: ctx.specialist,
      routing_reason: ctx.routingReason,
    },
    context: {
      orders: ctx.orderIds,
      transactions: ctx.transactionIds,
      prior_tickets: ctx.ticketIds,
      repeat_contacts: ctx.customer.repeatContacts,
      prior_refunds: ctx.customer.priorRefunds,
    },
    evidence: ctx.evidence,
    hypotheses: ctx.hypotheses,
    root_cause: ctx.rootCause,
    root_cause_confidence: ctx.rootCauseConfidence,
    contradictions: ctx.contradictions,
    four_gates: ctx.gates,
    policy: ctx.policy,
    authority: ctx.authority,
    risk: ctx.risk,
    actions_attempted: ctx.actionHistory,
    verification: ctx.verification,
    escalation: ctx.escalation,
    resolution_status: ctx.resolutionStatus,
    recommended_next_action: ctx.recommendedAction,
    know_vs_infer_vs_decide: {
      known: ctx.evidence.filter((e) => e.known).map((e) => ({ source: e.source, label: e.label })),
      inferred: ctx.evidence
        .filter((e) => !e.known)
        .map((e) => ({ source: e.source, label: e.label, detail: e.detail })),
      decided: {
        decision: ctx.resolved ? "AUTONOMOUSLY RESOLVED" : ctx.escalation ? "ESCALATED TO HUMAN" : "AWAITING ACTION",
        why: "Evidence + policy + authority + acceptable risk evaluated by deterministic four-gate controller",
      },
    },
  };
}

// --- _shared/engine/policy.ts ---
// =====================================================================
// ResolveAI engine — deterministic policy evaluation
// The LLM never invents policy: every decision reads policy rows and
// evaluates their conditions against collected facts.
// =====================================================================

export interface PolicyFacts {
  twoSuccessfulPaymentsSameOrder: boolean;
  amount: number;
  orderPending: boolean;
  within30Days: boolean;
  deliveryEvidenceComplete: boolean;
  noContradiction: boolean;
  identityVerified: boolean;
  defectConfirmed: boolean;
  fraudRisk: string;
}

export interface PolicyEvaluation {
  policyId: string | null;
  policyName: string | null;
  allowed: boolean;
  matchedConditions: { condition: string; satisfied: boolean }[];
  reason: string;
}

const FACT_KEYS: Record<string, keyof PolicyFacts> = {
  two_successful_payments_same_order: "twoSuccessfulPaymentsSameOrder",
  amount_within_authority: "amountWithinAuthority",
  within_30_days: "within30Days",
  order_pending: "orderPending",
  delivery_evidence_complete: "deliveryEvidenceComplete",
  no_contradiction: "noContradiction",
  identity_verified: "identityVerified",
  defect_confirmed: "defectConfirmed",
  fraud_risk: "fraudRisk",
};

export function evaluatePolicy(
  policies: PolicyRow[],
  action: string,
  facts: PolicyFacts,
): PolicyEvaluation {
  // Prefer policies that explicitly allow this action; evaluate conditions.
  const relevant = policies.filter((p) => p.allowed_actions.includes(action));
  if (relevant.length === 0) {
    return {
      policyId: null,
      policyName: null,
      allowed: false,
      matchedConditions: [],
      reason: `No policy permits action '${action}'`,
    };
  }

  let best: PolicyEvaluation | null = null;
  for (const policy of relevant) {
    const matchedConditions: { condition: string; satisfied: boolean }[] = [];
    let allTrue = true;
    for (const [key, expected] of Object.entries(policy.conditions)) {
      const factKey = FACT_KEYS[key];
      let satisfied: boolean;
      if (key === "amount_within_authority") {
        satisfied = facts.amountWithinAuthority;
      } else if (factKey) {
        satisfied = facts[factKey] === expected;
      } else {
        satisfied = true;
      }
      if (!satisfied) allTrue = false;
      matchedConditions.push({ condition: key, satisfied });
    }

    // If the policy has no conditions, its only requirement is that the
    // action is in allowed_actions (already satisfied by the filter).
    if (Object.keys(policy.conditions).length === 0) allTrue = true;

    const allowed = allTrue;
    if (allowed || !best) {
      best = {
        policyId: policy.policy_id,
        policyName: policy.name,
        allowed,
        matchedConditions,
        reason: allowed
          ? `Policy ${policy.policy_id} (${policy.name}) permits '${action}'`
          : `Policy ${policy.policy_id} (${policy.name}) conditions not met for '${action}'`,
      };
    }
  }

  return best!;
}

// --- _shared/engine/safety.ts ---
// =====================================================================
// ResolveAI engine — contradiction detection, fingerprint matching,
// circuit breaker. Pure TS.
// =====================================================================

// ---------------------------------------------------------------------
// Contradiction detection
// ---------------------------------------------------------------------
export interface DeliveryEvidence {
  orderStatus: string | null;
  shipmentStatus: string | null;
  courier?: string | null;
  gps: { matched?: boolean; distanceKm?: number; note?: string } | null;
  customerClaimsNotReceived: boolean;
}

export function detectContradictions(
  delivery: DeliveryEvidence | null,
): Contradiction[] {
  const found: Contradiction[] = [];

  if (delivery) {
    const delivered =
      delivery.orderStatus === "delivered" && delivery.shipmentStatus === "delivered";

    if (delivered && delivery.customerClaimsNotReceived) {
      if (delivery.gps && delivery.gps.matched === false) {
        found.push({
          id: "CTR-DLV-001",
          type: "delivery_contradiction",
          label: "Courier reports delivered, customer disputes, GPS location mismatch",
          evidence: [
            { source: "Order DB", value: "delivered" },
            { source: "Courier", value: `delivered (${delivery.courier ?? "unknown"})` },
            {
              source: "GPS",
              value: delivery.gps.distanceKm
                ? `delivery location ${delivery.gps.distanceKm} km from customer home (${delivery.gps.note ?? "no note"})`
                : "delivery location does not match customer home",
            },
          ],
          decision: "AUTO-RESOLUTION BLOCKED",
          impact: "HIGH — customer denies receipt while courier proof points to a different location; refunding or re-sending could be fraudulent or duplicate.",
          requiredAction: "Human investigation of courier proof-of-delivery vs customer address before any resolution.",
        });
      } else if (!delivery.gps || delivery.gps.matched == null) {
        found.push({
          id: "CTR-DLV-002",
          type: "delivery_evidence_missing",
          label: "Delivery confirmed but GPS proof-of-delivery unavailable",
          evidence: [
            { source: "Order DB", value: "delivered" },
            { source: "Courier", value: `delivered (${delivery.courier ?? "unknown"})` },
            { source: "GPS", value: "proof-of-delivery coordinates not recorded" },
          ],
          decision: "AUTO-RESOLUTION BLOCKED",
          impact: "MEDIUM — delivery record exists but cannot be verified geospatially.",
          requiredAction: "Request courier photographs/proof or re-verify with the courier partner.",
        });
      }
    }
  }

  return found;
}

// ---------------------------------------------------------------------
// Failure fingerprint matching
// ---------------------------------------------------------------------
export interface Fingerprint {
  fingerprint_id: string;
  name: string;
  symptoms: string[];
  affected_system: string;
  probable_root_cause: string;
  severity: string;
  recommended_recovery: string;
}

export interface FingerprintMatch {
  fingerprint: Fingerprint;
  coverage: number; // matched symptoms / total symptoms
  matchedSymptoms: string[];
}

export function matchFingerprint(
  symptoms: string[],
  fingerprints: Fingerprint[],
): FingerprintMatch | null {
  let best: FingerprintMatch | null = null;
  for (const fp of fingerprints) {
    const matched = symptoms.filter((s) => fp.symptoms.includes(s));
    const coverage = fp.symptoms.length ? matched.length / fp.symptoms.length : 0;
    if (matched.length > 0 && (!best || coverage > best.coverage)) {
      best = { fingerprint: fp, coverage, matchedSymptoms: matched };
    }
  }
  return best;
}

// ---------------------------------------------------------------------
// Circuit breaker
// ---------------------------------------------------------------------
export interface BreakerResult {
  tripped: boolean;
  attempts: number;
  limit: number;
  reason: string | null;
}

export function evaluateCircuitBreaker(
  actionHistory: { action: string; status: string }[],
  actionName: string,
  limit = 3,
): BreakerResult {
  const attempts = actionHistory.filter(
    (a) => a.action === actionName && a.status === "failed",
  ).length;
  return {
    tripped: attempts >= limit,
    attempts,
    limit,
    reason: attempts >= limit ? "Repeated action failure — automation paused" : null,
  };
}

// --- _shared/engine/trends.ts ---
// =====================================================================
// ResolveAI engine — recurring / emerging issue detection (pure TS)
// Compares current frequency of a fingerprint against a baseline window
// using real case records.
// =====================================================================
export interface TrendInputs {
  currentCount: number; // matching cases in the recent window
  baselineCount: number; // matching cases in the older (baseline) window
  baselineWindowCount: number; // total cases in baseline window
  currentWindowCount: number; // total cases in current window
  affectedCustomers: string[];
  relatedSystems: string[];
}

export interface TrendResult {
  currentFrequency: number;
  baselineFrequency: number;
  changePct: number; // (current - baseline) / baseline
  ratio: number;
  direction: "stable" | "declining" | "emerging";
  potentialIncident: boolean;
  severity: "low" | "medium" | "high";
  reason: string;
}

export function computeTrend(inputs: TrendInputs): TrendResult {
  const currentRate = inputs.currentWindowCount > 0 ? inputs.currentCount / inputs.currentWindowCount : 0;
  const baselineRate = inputs.baselineWindowCount > 0 ? inputs.baselineCount / inputs.baselineWindowCount : 0;
  const changePct = baselineRate > 0 ? Math.round(((currentRate - baselineRate) / baselineRate) * 100) : currentRate > 0 ? 100 : 0;
  const ratio = baselineRate > 0 ? currentRate / baselineRate : currentRate > 0 ? 1 : 0;

  let direction: TrendResult["direction"] = "stable";
  if (changePct >= 40 && currentCountIsSignificant(inputs)) direction = "emerging";
  else if (changePct <= -25) direction = "declining";

  const potentialIncident = direction === "emerging" && currentCountIsSignificant(inputs);
  const severity: TrendResult["severity"] = potentialIncident ? "high" : changePct >= 40 ? "medium" : "low";

  return {
    currentFrequency: inputs.currentCount,
    baselineFrequency: inputs.baselineCount,
    changePct,
    ratio: Math.round(ratio * 100) / 100,
    direction,
    potentialIncident,
    severity,
    reason:
      direction === "emerging"
        ? `Complaint rate up ${changePct}% vs baseline — potentially emerging issue across ${inputs.affectedCustomers.length} customer(s).`
        : direction === "declining"
          ? `Complaint rate down ${Math.abs(changePct)}% vs baseline.`
          : "Complaint rate is stable vs baseline.",
  };
}

function currentCountIsSignificant(inputs: TrendInputs): boolean {
  return inputs.currentCount >= 3;
}

