// --- _shared/engine/uncertainty.ts ---
// =====================================================================
// ResolveAI engine — uncertainty / low-confidence assessment (pure TS)
// Never presents uncertain hypotheses as confirmed facts.
// =====================================================================
export interface UncertaintyInputs {
  aiConfidence: number | null; // 0..1 routing/root-cause confidence
  evidenceCount: number;
  expectedEvidence: number; // ideal evidence items for this intent
  contradictions: number;
  policyCertain: boolean;
  actionRisk: "low" | "medium" | "high";
}

export interface UncertaintyResult {
  level: "LOW" | "MODERATE" | "HIGH";
  confidence: number | null;
  evidenceCompleteness: number; // 0..1
  evidenceConsistency: "consistent" | "conflicting" | "missing";
  policyCertainty: "certain" | "uncertain";
  actionRisk: "low" | "medium" | "high";
  missingEvidence: string[];
  blockAutoResolution: boolean;
  recommendHumanReview: boolean;
  reason: string;
}

export function assessUncertainty(inputs: UncertaintyInputs): UncertaintyResult {
  const evidenceCompleteness = Math.min(1, inputs.evidenceCount / Math.max(1, inputs.expectedEvidence));
  const consistency: UncertaintyResult["evidenceConsistency"] =
    inputs.contradictions > 0 ? "conflicting" : inputs.evidenceCount === 0 ? "missing" : "consistent";

  let level: UncertaintyResult["level"] = "LOW";
  const reasons: string[] = [];

  if (inputs.aiConfidence != null && inputs.aiConfidence < 0.6) {
    level = "HIGH";
    reasons.push(`AI confidence ${Math.round(inputs.aiConfidence * 100)}% is below the safe threshold (60%).`);
  } else if (inputs.aiConfidence != null && inputs.aiConfidence < 0.7) {
    level = "MODERATE";
    reasons.push(`AI confidence ${Math.round(inputs.aiConfidence * 100)}% is moderate.`);
  }

  if (evidenceCompleteness < 0.5) {
    if (level !== "HIGH") level = "MODERATE";
    reasons.push(`Evidence incomplete (${inputs.evidenceCount} of ${inputs.expectedEvidence} expected items).`);
  }

  if (consistency === "conflicting") {
    level = "HIGH";
    reasons.push(`${inputs.contradictions} contradictory finding(s) detected.`);
  }

  if (!inputs.policyCertain) {
    if (level !== "HIGH") level = "MODERATE";
    reasons.push("Policy applicability is uncertain.");
  }

  if (inputs.actionRisk === "high") {
    level = "HIGH";
    reasons.push("High-risk action involved.");
  }

  const blockAutoResolution = level === "HIGH" || consistency === "conflicting";
  const missingEvidence: string[] = [];
  if (evidenceCompleteness < 1) {
    if (!inputs.policyCertain) missingEvidence.push("A policy that clearly permits the proposed action");
    if (inputs.contradictions > 0) missingEvidence.push("Evidence that reconciles the contradiction");
    if (evidenceCompleteness < 0.5) missingEvidence.push(`Additional factual evidence (${Math.ceil(inputs.expectedEvidence - inputs.evidenceCount)} items)`);
  }

  return {
    level,
    confidence: inputs.aiConfidence,
    evidenceCompleteness: Math.round(evidenceCompleteness * 100) / 100,
    evidenceConsistency: consistency,
    policyCertainty: inputs.policyCertain ? "certain" : "uncertain",
    actionRisk: inputs.actionRisk,
    missingEvidence,
    blockAutoResolution,
    recommendHumanReview: blockAutoResolution || level === "MODERATE",
    reason: reasons.length > 0 ? reasons.join(" ") : "Evidence is sufficient and consistent; confidence is acceptable.",
  };
}

// --- _shared/events.ts ---
// =====================================================================
// ResolveAI — event / audit / analytics / case-update helpers
// (requires Enter Cloud db client — Deno only)
// =====================================================================

export async function emitCaseEvent(
  db: SupabaseClient,
  caseUuid: string,
  stage: string,
  label: string,
  status: "running" | "ok" | "warn" | "error",
  result: Record<string, unknown> = {},
  evidenceCount = 0,
  durationMs = 0,
  error?: string,
): Promise<void> {
  await db.from("resolveai_case_events").insert({
    case_id: caseUuid,
    stage,
    label,
    status,
    result,
    evidence_count: evidenceCount,
    duration_ms: durationMs,
    error: error ?? null,
  });
}

export async function emitAudit(
  db: SupabaseClient,
  caseUuid: string,
  actor: string,
  agent: string,
  action: string,
  fields: {
    input?: Record<string, unknown>;
    decision?: Record<string, unknown>;
    evidence?: Record<string, unknown>;
    policy?: Record<string, unknown>;
    authority?: Record<string, unknown>;
    risk?: Record<string, unknown>;
    result?: Record<string, unknown>;
    verification?: Record<string, unknown>;
  } = {},
): Promise<void> {
  await db.from("resolveai_audit_logs").insert({
    case_id: caseUuid,
    actor,
    agent,
    action,
    input: fields.input ?? {},
    decision: fields.decision ?? {},
    evidence: fields.evidence ?? {},
    policy: fields.policy ?? {},
    authority: fields.authority ?? {},
    risk: fields.risk ?? {},
    result: fields.result ?? {},
    verification: fields.verification ?? {},
  });
}

export async function emitAnalytics(
  db: SupabaseClient,
  customerUuid: string | null,
  caseUuid: string | null,
  eventType: string,
  payload: Record<string, unknown> = {},
): Promise<void> {
  await db.from("resolveai_analytics_events").insert({
    customer_id: customerUuid,
    case_id: caseUuid,
    event_type: eventType,
    payload,
  });
}

export async function updateCase(
  db: SupabaseClient,
  caseUuid: string,
  patch: Record<string, unknown>,
): Promise<void> {
  await db.from("resolveai_cases").update(patch).eq("id", caseUuid);
}

export const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// --- _shared/incidents.ts ---
// =====================================================================
// ResolveAI — incident detection from failure fingerprints
// (Deno only)
// =====================================================================

const INCIDENT_THRESHOLD = 5;

/**
 * Match a case's symptoms against known failure fingerprints. When a
 * fingerprint's frequency crosses the incident threshold, create/refresh
 * an incident and link the case.
 */
export async function detectAndRecordIncident(
  db: SupabaseClient,
  caseUuid: string,
  symptoms: string[],
  rootCauseLabel: string | null,
): Promise<void> {
  const { data: fingerprints } = await db
    .from("resolveai_failure_fingerprints")
    .select("*");
  if (!fingerprints || fingerprints.length === 0) return;

  const match = matchFingerprint(symptoms, fingerprints as unknown as Fingerprint[]);
  if (!match) return;

  const fp = match.fingerprint;

  // Increment frequency
  const { data: fpRow } = await db
    .from("resolveai_failure_fingerprints")
    .select("frequency")
    .eq("fingerprint_id", fp.fingerprint_id)
    .maybeSingle();
  const newFreq = ((fpRow as { frequency?: number } | null)?.frequency ?? fp.frequency) + 1;
  await db
    .from("resolveai_failure_fingerprints")
    .update({ frequency: newFreq })
    .eq("fingerprint_id", fp.fingerprint_id);

  const isIncident = newFreq >= INCIDENT_THRESHOLD;
  if (!isIncident) return;

  // Upsert incident by fingerprint
  const incidentName =
    fp.affected_system === "payment-order-sync"
      ? "Payment Gateway Duplicate Debits"
      : fp.affected_system === "logistics"
        ? "Delivery GPS Discrepancies"
        : `${fp.name} (detected)`;

  const { data: existing } = await db
    .from("resolveai_incidents")
    .select("id")
    .eq("fingerprint_id", (fp as unknown as { id: string }).id ?? "")
    .maybeSingle();

  let incidentUuid: string;
  if (existing) {
    incidentUuid = (existing as { id: string }).id;
    const { data: linked } = await db
      .from("resolveai_incident_cases")
      .select("case_id")
      .eq("incident_id", incidentUuid);
    const linkedIds = (linked ?? []).map((r) => (r as { case_id: string }).case_id);
    if (!linkedIds.includes(caseUuid)) {
      await db.from("resolveai_incident_cases").insert({ incident_id: incidentUuid, case_id: caseUuid });
    }
    const count = linkedIds.length + 1;
    await db
      .from("resolveai_incidents")
      .update({
        affected_case_count: count,
        updated_at: new Date().toISOString(),
        name: incidentName,
        severity: fp.severity === "critical" ? "critical" : fp.severity === "high" ? "high" : "medium",
      })
      .eq("id", incidentUuid);
  } else {
    const { data: fpFull } = await db
      .from("resolveai_failure_fingerprints")
      .select("id")
      .eq("fingerprint_id", fp.fingerprint_id)
      .maybeSingle();
    const { data: newInc } = await db
      .from("resolveai_incidents")
      .insert({
        incident_id: `INC-${String(Math.floor(8000 + Math.random() * 999)).slice(0, 4)}`,
        fingerprint_id: (fpFull as { id: string }).id,
        name: incidentName,
        status: "active",
        affected_case_count: 1,
        first_detected_at: new Date().toISOString(),
        severity: fp.severity === "critical" ? "critical" : fp.severity === "high" ? "high" : "medium",
        recommended_response: fp.recommended_recovery,
      })
      .select("id")
      .single();
    incidentUuid = (newInc as { id: string }).id;
    await db.from("resolveai_incident_cases").insert({ incident_id: incidentUuid, case_id: caseUuid });
  }
  console.log(`incident: case ${caseUuid} linked to fingerprint ${fp.fingerprint_id} (${rootCauseLabel ?? "unknown root cause"})`);
}

// --- _shared/lifecycle.ts ---
// =====================================================================
// ResolveAI — lifecycle orchestrator (supervisor agent)
//
// Customer message → context → understanding → routing → specialist
// investigation → RAG retrieval → root-cause analysis → four-gate
// controller → action (circuit breaker + verification) → resolve or
// escalate → audit → analytics → incident detection.
//
// The LLM proposes; deterministic code controls execution.
// =====================================================================

export interface LifecycleRequest {
  customerId: string; // resolveai_customers.id
  message: string;
  staffRole?: string | null;
  actor?: string;
  fast?: boolean; // true disables the demo pacing delays (self-check)
  skipLlm?: boolean; // true disables LLM calls (self-check runs deterministic-only)
  earlyReturn?: boolean; // create case + first events, return immediately (live "start")
  existingCaseUuid?: string; // continue an existing case (live "continue")
  existingConversationUuid?: string | null; // reuse conversation on continue
}

export interface LifecycleResult {
  caseUuid: string;
  caseId: string;
  conversationUuid: string | null;
  response: string;
  status: string;
  resolutionStatus: string | null;
  intent: string;
  specialist: string;
  escalationScore: number | null;
  snapshot: Record<string, unknown>;
}

const MIN_AUTO_CONFIDENCE = 0.6;
const STAGE_DELAY = 420;
const ACTION_DELAY = 500;

async function nextCaseId(db: SupabaseClient): Promise<string> {
  const { data } = await db
    .from("resolveai_cases")
    .select("case_id")
    .order("case_id", { ascending: false })
    .limit(1);
  const last = data && data.length > 0
    ? Number((data[0] as { case_id: string }).case_id.slice(3))
    : 5000;
  return `CS-${String(last + 1).padStart(4, "0")}`;
}

export async function runLifecycle(
  db: SupabaseClient,
  req: LifecycleRequest,
): Promise<LifecycleResult> {
  const delay = req.fast ? 0 : STAGE_DELAY;
  const actor = req.actor ?? "customer";

  // -----------------------------------------------------------------
  // 1. Customer + context
  // -----------------------------------------------------------------
  const { data: customer } = await db
    .from("resolveai_customers")
    .select("*")
    .eq("id", req.customerId)
    .maybeSingle();
  if (!customer) {
    throw new Error("customer_not_found");
  }
  const cust = customer as Record<string, unknown>;

  const [{ data: orders }, { data: payments }, { data: tickets }, { data: conversations }] =
    await Promise.all([
      db.from("resolveai_orders").select("*").eq("customer_id", req.customerId).order("created_at", { ascending: false }).limit(8),
      db.from("resolveai_payments").select("*").eq("customer_id", req.customerId).order("created_at", { ascending: false }).limit(12),
      db.from("resolveai_tickets").select("*").eq("customer_id", req.customerId).order("created_at", { ascending: false }).limit(10),
      db.from("resolveai_conversations").select("*").eq("customer_id", req.customerId).eq("status", "active").limit(1),
    ]);

  const openConvo = conversations && conversations.length > 0
    ? (conversations[0] as { id: string })
    : null;
  const repeatContacts = (tickets ?? []).length;

  // Conversation + message + Case Twin row.
  // On "continue" the case already exists (created by the "start" call).
  let convoUuid = req.existingConversationUuid ?? openConvo?.id ?? null;
  let caseUuid: string;
  let caseId: string;
  const message = req.message.trim() || "";

  if (req.existingCaseUuid) {
    caseUuid = req.existingCaseUuid;
    const { data: existing, error: existingErr } = await db
      .from("resolveai_cases")
      .select("case_id, conversation_id, message_text")
      .eq("id", caseUuid)
      .maybeSingle();
    if (existingErr || !existing) throw new Error("case_not_found");
    const ex = existing as { case_id: string; conversation_id: string | null; message_text: string | null };
    caseId = ex.case_id;
    convoUuid = convoUuid ?? ex.conversation_id;
    const baseMessage = message || ex.message_text || "";
    // Ensure at least one customer message exists for the pipeline.
    if (!baseMessage) throw new Error("message_required");
  } else {
    if (!convoUuid) {
      const { data: newConvo } = await db
        .from("resolveai_conversations")
        .insert({ customer_id: req.customerId, status: "active" })
        .select("id")
        .single();
      convoUuid = (newConvo as { id: string }).id;
    }
    await db.from("resolveai_messages").insert({
      conversation_id: convoUuid,
      role: "customer",
      content: message,
    });
    caseId = await nextCaseId(db);
    caseUuid = crypto.randomUUID();
    await db.from("resolveai_cases").insert({
      id: caseUuid,
      case_id: caseId,
      customer_id: req.customerId,
      conversation_id: convoUuid,
      message_text: message,
      status: "investigating",
      created_at: new Date().toISOString(),
    });
  }

  // -----------------------------------------------------------------
  // 2. Understanding (LLM + deterministic fusion)
  // -----------------------------------------------------------------
  if (!req.existingCaseUuid) {
    await emitCaseEvent(db, caseUuid, "evidence_ingest", "Evidence Ingest", "running");
    await sleep(delay);
    await emitCaseEvent(db, caseUuid, "understanding", "AI Understanding", "running");
  }

  if (req.earlyReturn) {
    // Live "start": create the case, emit the first stage events and a
    // deterministic intent, then hand control back so the Glass Box can
    // subscribe and watch the continuation stream in via realtime.
    const detIntent = routeTicket({ message, customerRepeatContacts: repeatContacts, llmUnderstanding: null });
    await updateCase(db, caseUuid, { intent: detIntent.intent, priority: detIntent.priority, sentiment: detIntent.sentiment, urgency: detIntent.urgency });
    await emitCaseEvent(db, caseUuid, "understanding", "AI Understanding", "ok", {
      intent: detIntent.intent,
      sub_intents: detIntent.subIntents,
      urgency: detIntent.urgency,
      sentiment: detIntent.sentiment,
      status: "investigation_started",
    });
    return {
      caseUuid,
      caseId,
      conversationUuid: convoUuid,
      response: "",
      status: "investigating",
      resolutionStatus: "INVESTIGATION IN PROGRESS",
      intent: detIntent.intent,
      specialist: detIntent.specialist,
      escalationScore: null,
      snapshot: {},
    };
  }

  const customerContext = [
    `tier ${cust.tier}`,
    `lifetime value ₹${cust.lifetime_value}`,
    `${repeatContacts} previous support contacts`,
    `${(tickets ?? []).length} prior tickets`,
    `${(orders ?? []).length} orders`,
  ].join(", ");
  const llmU = req.skipLlm ? null : await llmUnderstand(message, customerContext);
  const routed = routeTicket({
    message: message,
    customerRepeatContacts: repeatContacts,
    llmUnderstanding: llmU,
  });
  const slaDeadline = new Date(
    Date.now() + (SLA_HOURS[routed.priority] ?? 24) * 3600_000,
  ).toISOString();
  await updateCase(db, caseUuid, {
    intent: routed.intent,
    sub_intents: routed.subIntents,
    urgency: routed.urgency,
    sentiment: routed.sentiment,
    sentiment_score: routed.sentimentScore,
    priority: routed.priority,
    specialist: routed.specialist,
    routing_reason: routed.routingReason,
    routing_confidence: routed.confidence,
    sla_deadline: slaDeadline,
  });
  await emitCaseEvent(db, caseUuid, "understanding", "AI Understanding", "ok", {
    intent: routed.intent,
    sub_intents: routed.subIntents,
    urgency: routed.urgency,
    sentiment: routed.sentiment,
    confidence: routed.confidence,
  });

  // -----------------------------------------------------------------
  // 3. Specialist investigation
  // -----------------------------------------------------------------
  const evidence: EvidenceItem[] = [];
  evidence.push({
    id: "EV-CUST-1",
    source: "customers",
    type: "customer_profile",
    label: `Customer ${cust.name} (${cust.tier} tier)`,
    value: cust.customer_code,
    known: true,
  });

  // Order audit
  await emitCaseEvent(db, caseUuid, "order_audit", "Order Audit", "running");
  await sleep(delay);
  const orderList = (orders ?? []).map((o) => o as Record<string, unknown>);
  for (const o of orderList.slice(0, 3)) {
    evidence.push({
      id: `EV-ORD-${String(o.order_id)}`,
      source: "orders",
      type: "order",
      label: `Order ${o.order_id}: ${o.status} (₹${o.amount})`,
      value: o.order_id,
      known: true,
    });
  }
  const pendingOrders = orderList.filter((o) => o.status === "pending");
  await emitCaseEvent(db, caseUuid, "order_audit", "Order Audit", "ok", {
    orders_found: orderList.length,
    pending: pendingOrders.length,
  }, evidence.length);

  // Payment audit
  await emitCaseEvent(db, caseUuid, "payment_audit", "Payment Audit", "running");
  await sleep(delay);
  const payList = (payments ?? []).map((p) => p as Record<string, unknown>);
  const succeeded = payList.filter((p) => p.status === "succeeded");
  for (const p of payList.slice(0, 6)) {
    evidence.push({
      id: `EV-PAY-${String(p.txn_id)}`,
      source: "payments",
      type: "payment",
      label: `Payment ${p.txn_id}: ${p.status} (₹${p.amount})`,
      value: p.txn_id,
      known: true,
    });
  }
  // Duplicate detection: ≥2 succeeded payments on the same order
  const byOrder = new Map<string, Record<string, unknown>[]>();
  for (const p of succeeded) {
    const key = String(p.order_id);
    if (!byOrder.has(key)) byOrder.set(key, []);
    byOrder.get(key)!.push(p);
  }
  const duplicateGroups = [...byOrder.values()].filter((g) => g.length >= 2);
  const hasDuplicates = duplicateGroups.length > 0;
  const duplicateTarget = duplicateGroups.length > 0
    ? duplicateGroups[0].sort(
        (a, b) => new Date(String(b.created_at)).getTime() - new Date(String(a.created_at)).getTime(),
      )[0]
    : null;
  const duplicateAmount = duplicateTarget ? Number(duplicateTarget.amount) : null;

  if (hasDuplicates && duplicateTarget) {
    evidence.push({
      id: "EV-DUP-1",
      source: "payments",
      type: "duplicate_payment",
      label: `Duplicate charge detected: ${duplicateGroups[0].length} successful payments on same order`,
      value: duplicateTarget.txn_id,
      known: true,
    });
  }
  // Sync issue: succeeded payment(s) + pending order
  const pendingOrderIds = new Set(pendingOrders.map((o) => String(o.id)));
  const syncIssue = succeeded.some((p) => pendingOrderIds.has(String(p.order_id)));
  if (syncIssue) {
    evidence.push({
      id: "EV-SYNC-1",
      source: "orders",
      type: "payment_order_sync",
      label: "Payment captured but order still pending — synchronization discrepancy",
      value: pendingOrders[0]?.order_id,
      known: true,
    });
  }
  await emitCaseEvent(db, caseUuid, "payment_audit", "Payment Audit", "ok", {
    transactions_found: payList.length,
    succeeded: succeeded.length,
    duplicate_detected: hasDuplicates,
  }, evidence.length);

  // Ticket history
  await emitCaseEvent(db, caseUuid, "ticket_history", "Ticket History", "running");
  await sleep(delay);
  const ticketList = (tickets ?? []).map((t) => t as Record<string, unknown>);
  for (const t of ticketList.slice(0, 4)) {
    evidence.push({
      id: `EV-TCK-${String(t.ticket_id)}`,
      source: "tickets",
      type: "ticket",
      label: `Ticket ${t.ticket_id}: ${t.subject}`,
      value: t.ticket_id,
      known: true,
    });
  }
  await emitCaseEvent(db, caseUuid, "ticket_history", "Ticket History", "ok", {
    prior_tickets: ticketList.length,
  }, evidence.length);

  // -----------------------------------------------------------------
  // 4. Knowledge retrieval (RAG)
  // -----------------------------------------------------------------
  await emitCaseEvent(db, caseUuid, "knowledge_retrieval", "Knowledge Retrieval", "running");
  await sleep(delay);
  const searchQuery = message.toLowerCase().slice(0, 120);
  const { data: rag } = await db.rpc("resolveai_search_knowledge", {
    query: searchQuery,
    max_results: 4,
  });
  const ragRows = (rag ?? []) as Record<string, unknown>[];
  const sources = ragRows.map((r) => ({
    doc_id: r.doc_id,
    title: r.title,
    section: `chunk #${r.chunk_index}`,
    score: Number(r.score ?? 0),
    reason: r.title,
  }));
  for (const r of ragRows) {
    evidence.push({
      id: `EV-RAG-${String(r.doc_id)}-${String(r.chunk_index)}`,
      source: "knowledge",
      type: "rag_chunk",
      label: `${r.title} (${r.category}) — ${String(r.content).slice(0, 90)}…`,
      value: { doc_id: r.doc_id, score: r.score },
      known: true,
      detail: `Retrieved with score ${Number(r.score ?? 0).toFixed(3)}`,
    });
  }
  await emitCaseEvent(db, caseUuid, "knowledge_retrieval", "Knowledge Retrieval", "ok", {
    sources,
    retrieved: ragRows.length,
  }, evidence.length);

  // -----------------------------------------------------------------
  // 5. Policy evaluation
  // -----------------------------------------------------------------
  await emitCaseEvent(db, caseUuid, "policy_evaluation", "Policy Evaluation", "running");
  await sleep(delay);
  const { data: policies } = await db.from("resolveai_policies").select("*");
  const policyRows = (policies ?? []) as Record<string, unknown>[];

  const recommendedAction = hasDuplicates && routed.intent === "billing" && duplicateTarget
    ? { action: "issue_refund", payment_txn: duplicateTarget.txn_id, amount: duplicateAmount }
    : { action: "update_ticket", note: "Investigation completed; needs specialist handling" };

  const facts = {
    twoSuccessfulPaymentsSameOrder: hasDuplicates,
    amount: duplicateAmount ?? 0,
    amountWithinAuthority: duplicateAmount != null
      ? duplicateAmount <= (AUTHORITY_LIMITS[String(cust.tier)] ?? 1000)
      : false,
    orderPending: pendingOrders.length > 0,
    within30Days: true,
    deliveryEvidenceComplete: true,
    noContradiction: true, // set below after contradiction detection
    identityVerified: true,
    defectConfirmed: false,
    fraudRisk: "low",
  };
  const policyEval = evaluatePolicy(
    policyRows as never,
    recommendedAction.action,
    facts,
  );
  await emitCaseEvent(db, caseUuid, "policy_evaluation", "Policy Evaluation", "ok", {
    policy: policyEval.policyId,
    allowed: policyEval.allowed,
    reason: policyEval.reason,
  }, evidence.length);

  // -----------------------------------------------------------------
  // 6. Root-cause analysis + contradiction detection
  // -----------------------------------------------------------------
  await emitCaseEvent(db, caseUuid, "root_cause_analysis", "Root Cause Analysis", "running");
  await sleep(delay);

  const customerClaimsNotReceived = /not received|never received|missing package|didn.t get|not got|not deliver/i.test(message);
  const deliveryOrder = orderList.find((o) => o.status === "delivered");
  const contradictions: Contradiction[] = deliveryOrder
    ? detectContradictions({
        orderStatus: String(deliveryOrder.status),
        shipmentStatus: String(deliveryOrder.shipment_status ?? ""),
        courier: deliveryOrder.courier ? String(deliveryOrder.courier) : null,
        gps: (deliveryOrder.gps_evidence as { matched?: boolean; distanceKm?: number; note?: string } | null) ?? null,
        customerClaimsNotReceived,
      })
    : [];

  const symptoms: string[] = [];
  if (hasDuplicates) symptoms.push("duplicate_transaction");
  if (syncIssue) symptoms.push("order_still_pending");
  if (contradictions.length > 0) {
    symptoms.push("customer_disputes", "gps_location_mismatch");
    if (deliveryOrder?.shipment_status === "delivered") symptoms.push("courier_claims_delivered");
  }

  // Deterministic root cause takes precedence when evidence is strong.
  let rootCause: string | null = null;
  let rootConfidence: number | null = null;
  let hypotheses: Hypothesis[] = [];
  const evidenceSummary = evidence.map((e) => `- [${e.source}] ${e.label}`).join("\n");
  const llmHyp = req.skipLlm ? null : await llmHypothesize(message, evidenceSummary);
  if (llmHyp) {
    hypotheses = llmHyp.hypotheses.map((h, i) => ({
      ...h,
      evidenceIds: evidence.slice(0, 3).map((e) => e.id),
      confidence: Math.max(0, h.confidence),
    }));
  }

  if (hasDuplicates && routed.intent === "billing") {
    rootCause = syncIssue
      ? "Payment/order synchronization failure — duplicate debit created while order stayed pending"
      : "Duplicate debit — two successful transactions recorded for the same order";
    rootConfidence = 0.92;
    hypotheses.unshift({
      title: "Duplicate payment (gateway timeout pattern)",
      reasoning: "2 successful transactions share one order id; matches the gateway-timeout duplicate-debit pattern (DOC-PAY-01).",
      confidence: 0.92,
      evidenceIds: ["EV-DUP-1"],
    });
  } else if (contradictions.length > 0) {
    rootCause = contradictions[0].label;
    rootConfidence = 0.88;
  } else if (llmHyp) {
    rootCause = llmHyp.root_cause;
    rootConfidence = llmHyp.hypotheses[0]?.confidence ?? 0.6;
  } else {
    rootCause = syncIssue
      ? "Payment captured while order remained pending"
      : "No dominant root cause — insufficient evidence";
    rootConfidence = syncIssue ? 0.8 : 0.51;
  }

  facts.noContradiction = contradictions.length === 0;
  await emitCaseEvent(db, caseUuid, "root_cause_analysis", "Root Cause Analysis", "ok", {
    root_cause: rootCause,
    confidence: rootConfidence,
    hypotheses: hypotheses.length,
    contradictions: contradictions.length,
  }, evidence.length);

  if (contradictions.length > 0) {
    await emitCaseEvent(db, caseUuid, "contradiction_check", "Contradiction Check", "warn", {
      contradictions: contradictions.map((c) => ({ type: c.type, label: c.label, evidence: c.evidence })),
    }, evidence.length);
  }

  // -----------------------------------------------------------------
  // 7. Four-gate controller
  // -----------------------------------------------------------------
  await emitCaseEvent(db, caseUuid, "four_gate_controller", "Four-Gate Controller", "running");
  await sleep(delay);
  const uncertainty = hasDuplicates ? 0.1 : contradictions.length > 0 ? 0.3 : 0.35;
  const gateInputs: GateInputs = {
    evidence,
    action: recommendedAction.action,
    amount: duplicateAmount,
    customerTier: String(cust.tier),
    staffRole: req.staffRole ?? null,
    policyAllowed: policyEval.allowed,
    policyId: policyEval.policyId,
    contradictions: contradictions.length,
    repeatContacts,
    sentiment: routed.sentiment,
    uncertainty,
    highValueCustomer: Number(cust.lifetime_value) >= 30000,
    hasDuplicates,
    actionFailures: 0,
  };
  const gates = evaluateAllGates(gateInputs);
  await updateCase(db, caseUuid, {
    evidence,
    evidence_count: evidence.length,
    hypotheses,
    root_cause: rootCause,
    root_cause_confidence: rootConfidence,
    contradictions,
    contradiction_detected: contradictions.length > 0,
    gates: gates.gates,
    recommended_action: recommendedAction,
    policy_result: { policy_id: policyEval.policyId, allowed: policyEval.allowed, reason: policyEval.reason },
    authority_result: gates.gates.authority,
    risk_result: gates.gates.risk,
  });
  await emitCaseEvent(db, caseUuid, "four_gate_controller", "Four-Gate Controller", "ok", {
    gates: Object.fromEntries(
      Object.entries(gates.gates).map(([k, g]) => [k, { status: g.status, detail: g.detail }]),
    ),
    can_auto_resolve: gates.canAutoResolve,
  });

  // -----------------------------------------------------------------
  // 8. Decision: act / resolve / escalate
  // -----------------------------------------------------------------
  const confidence = rootConfidence ?? routed.confidence;
  let response = "";
  let status = "action_required";
  let resolutionStatus: string | null = null;
  let escalationScore: number | null = null;
  let verification: { overall: string; checks: unknown[] } | null = null;

  // ---- Track B: contradiction → block + escalate ----
  if (contradictions.length > 0) {
    resolutionStatus = "ESCALATED — CONTRADICTION";
    status = "escalated";
    const esc = computeEscalation({
      intent: routed.intent,
      caseComplexity: 0.7,
      repeatContacts,
      sentiment: routed.sentiment,
      financialImpact: duplicateAmount ?? 0,
      policyUncertainty: false,
      conflictingEvidence: true,
      aiConfidence: confidence,
      actionFailures: 0,
      slaRisk: false,
    });
    escalationScore = esc.score;
    await recordEscalation(db, caseUuid, esc, contradictions, {
      caseId, customer: cust, message: message, intent: routed.intent,
      evidence, hypotheses, rootCause, rootConfidence, gates, recommendedAction,
      tickets, orders, payments, sentiment: routed.sentiment, urgency: routed.urgency,
      conversation: null,
    });
    status = "escalated";
  }
  // ---- Track A: autonomous resolution ----
  else if (
    gates.canAutoResolve &&
    confidence >= MIN_AUTO_CONFIDENCE &&
    recommendedAction.action === "issue_refund" &&
    duplicateTarget
  ) {
    status = "verifying";
    await emitCaseEvent(db, caseUuid, "action", "Action — issue_refund", "running", {
      attempt: 1,
      payment_txn: duplicateTarget.txn_id,
      amount: duplicateAmount,
    });
    await updateCase(db, caseUuid, { status: "action_required" });

    let outcome: { status: string; overall: string; detail: string; refundId?: string } | null = null;
    const attempts: Record<string, unknown>[] = [];
    const actionId = await recordAgentAction(
      db, caseUuid, routed.specialist, "issue_refund", "executing",
      { payment_txn: duplicateTarget.txn_id, amount: duplicateAmount }, {},
    );

    for (let attempt = 1; attempt <= 3 && !outcome; attempt++) {
      const res = await executeRefund(db, {
        caseUuid,
        caseId,
        customerId: req.customerId,
        paymentUuid: String(duplicateTarget.id),
        amount: duplicateAmount!,
        agentKey: routed.specialist,
      });
      const record: Record<string, unknown> = {
        attempt,
        status: res.action.status,
        error: res.action.error ?? null,
        detail: res.action.detail,
      };
      attempts.push(record);
      await recordAgentAction(
        db, caseUuid, routed.specialist, "issue_refund",
        res.action.status === "succeeded" ? "succeeded" : "failed",
        { attempt, payment_txn: duplicateTarget.txn_id },
        { detail: res.action.detail },
        res.action.error,
      );
      await recordVerification(db, actionId, caseUuid, res.verification);

      if (res.action.status === "succeeded") {
        outcome = {
          status: "resolved",
          overall: res.verification.overall,
          detail: res.action.detail,
          refundId: res.action.output.refund_id as string,
        };
        verification = res.verification;
        break;
      }
      if (res.verification.overall === "failed" && res.action.status === "blocked") {
        // Refund created but not verifiable → do NOT claim success.
        outcome = {
          status: "verification_failed",
          overall: "failed",
          detail: res.verification.detail,
          refundId: res.action.output.refund_id as string,
        };
        verification = res.verification;
        break;
      }
      // Execution failure → retry (circuit breaker will stop the loop)
      await emitCaseEvent(db, caseUuid, "action", `Action — issue_refund (attempt ${attempt} failed)`, "warn", {
        attempt,
        error: res.action.error,
      });
      await sleep(req.fast ? 0 : ACTION_DELAY);
    }

    if (outcome?.status === "resolved") {
      await emitCaseEvent(db, caseUuid, "action", "Action — issue_refund", "ok", {
        status: "succeeded",
        refund_id: outcome.refundId,
      });
      await sleep(req.fast ? 0 : 250);
      // Verification event
      await emitCaseEvent(db, caseUuid, "verification", "Verification", "ok", {
        overall: verification?.overall ?? "passed",
        checks: verification?.checks ?? [],
      });
      await updateCase(db, caseUuid, {
        verification_result: verification ?? {},
        action_history: attempts,
        status: "resolved",
        resolution_status: "RESOLVED — refund issued & verified",
        closed_at: new Date().toISOString(),
      });
      resolutionStatus = "RESOLVED";
      status = "resolved";
      await emitAnalytics(db, req.customerId, caseUuid, "case_resolved", {
        intent: routed.intent,
        action: "issue_refund",
      });
      await recordIncidentAndAudit(db, caseUuid, symptoms, rootCause, {
        actor, agent: routed.specialist, action: "issue_refund",
        decision: { gates: "PASS", confidence }, policy: { policy_id: policyEval.policyId },
        authority: gates.gates.authority, risk: gates.gates.risk,
        result: { refund_id: outcome.refundId, status: "issued" },
        verification,
      });
    } else {
      // ---- Track C: circuit breaker ----
      const breaker = {
        tripped: (attempts.filter((a) => a.status === "failed").length) >= 3,
        attempts: attempts.length,
        limit: 3,
      };
      await updateCase(db, caseUuid, {
        action_history: attempts,
        circuit_breaker: breaker,
        verification_result: verification ?? { overall: "unknown", checks: [] },
      });
      if (breaker.tripped) {
        await emitCaseEvent(db, caseUuid, "circuit_breaker", "Circuit Breaker", "error", {
          reason: "Repeated action failure — automation paused",
          attempts,
        });
        await emitCaseEvent(db, caseUuid, "action", "Action — issue_refund", "error", {
          error: "refund_api_unavailable",
        });
        status = "automation_paused";
        resolutionStatus = "ESCALATED — AUTOMATION PAUSED (CIRCUIT BREAKER)";
        const esc = computeEscalation({
          intent: routed.intent,
          caseComplexity: 0.6,
          repeatContacts,
          sentiment: routed.sentiment,
          financialImpact: duplicateAmount ?? 0,
          policyUncertainty: false,
          conflictingEvidence: false,
          aiConfidence: confidence,
          actionFailures: attempts.filter((a) => a.status === "failed").length,
          slaRisk: false,
        });
        escalationScore = esc.score;
        await recordEscalation(db, caseUuid, esc, [], {
          caseId, customer: cust, message: message, intent: routed.intent,
          evidence, hypotheses, rootCause, rootConfidence, gates, recommendedAction,
          tickets, orders, payments, sentiment: routed.sentiment, urgency: routed.urgency,
          conversation: null,
          circuitBreaker: breaker,
        });
        status = "escalated";
      } else {
        // Verification failed without breaker trip
        await emitCaseEvent(db, caseUuid, "verification", "Verification", "error", {
          overall: "failed",
          detail: outcome?.detail ?? "Action result could not be verified",
        });
        resolutionStatus = "VERIFICATION FAILED — ESCALATED";
        status = "escalated";
        const esc = computeEscalation({
          intent: routed.intent, caseComplexity: 0.6, repeatContacts,
          sentiment: routed.sentiment, financialImpact: duplicateAmount ?? 0,
          policyUncertainty: false, conflictingEvidence: false, aiConfidence: confidence,
          actionFailures: 1, slaRisk: false,
        });
        escalationScore = esc.score;
        await recordEscalation(db, caseUuid, esc, [], {
          caseId, customer: cust, message: message, intent: routed.intent,
          evidence, hypotheses, rootCause, rootConfidence, gates, recommendedAction,
          tickets, orders, payments, sentiment: routed.sentiment, urgency: routed.urgency,
          conversation: null,
        });
        status = "escalated";
      }
      await emitAnalytics(db, req.customerId, caseUuid, "action_failed", {
        intent: routed.intent, action: "issue_refund",
      });
    }
  }
  // ---- Low confidence / no permitted action → evaluate escalation ----
  else {
    const esc = computeEscalation({
      intent: routed.intent,
      caseComplexity: 0.5,
      repeatContacts,
      sentiment: routed.sentiment,
      financialImpact: duplicateAmount ?? 0,
      policyUncertainty: !policyEval.allowed,
      conflictingEvidence: false,
      aiConfidence: confidence,
      actionFailures: 0,
      slaRisk: routed.priority === "P1",
    });
    if (esc.score >= 55 || !gates.canAutoResolve) {
      escalationScore = esc.score;
      resolutionStatus = `ESCALATED — ${confidence < MIN_AUTO_CONFIDENCE ? "LOW CONFIDENCE" : "GATE NOT PASSED"}`;
      status = "escalated";
      await recordEscalation(db, caseUuid, esc, [], {
        caseId, customer: cust, message: message, intent: routed.intent,
        evidence, hypotheses, rootCause, rootConfidence, gates, recommendedAction,
        tickets, orders, payments, sentiment: routed.sentiment, urgency: routed.urgency,
        conversation: null,
      });
    } else {
      status = "action_required";
      resolutionStatus = "AWAITING SPECIALIST ACTION";
      await updateCase(db, caseUuid, { status: "action_required", resolution_status: resolutionStatus });
    }
  }

  // -----------------------------------------------------------------
  // 9. Customer-facing response
  // -----------------------------------------------------------------
  const respContext = [
    `Customer: ${cust.name}`,
    `Intent: ${routed.intent}`,
    `Root cause: ${rootCause ?? "not determined"}`,
    status === "resolved" ? "Action: refund issued and verified." : "",
    status === "escalated" ? "Action: escalated to human support team." : "",
    verification?.overall === "passed"
      ? `VERIFIED FACT: a refund of ₹${duplicateAmount ?? ""} (INR ${duplicateAmount ?? ""}) was issued and verified. State this exact amount. Never invent or convert amounts.`
      : "",
  ].filter(Boolean).join("\n");
  const llmReply = req.skipLlm ? null : await llmRespond(String(cust.name), respContext);

  // Correctness guard: a verified refund must be quoted with the exact amount.
  const exactRefundReply =
    status === "resolved" && duplicateAmount != null && llmReply && llmReply.includes(String(duplicateAmount))
      ? llmReply
      : null;
  response = exactRefundReply || fallbackResponse(status === "resolved", {
    customerName: String(cust.name),
    intent: routed.intent,
    rootCause,
    contradiction: contradictions.length > 0,
    refundIssued: status === "resolved",
    escalated: status === "escalated" || status === "automation_paused",
  });
  await executeSendMessage(db, {
    conversationUuid: convoUuid,
    content: response,
    agentKey: "supervisor",
  });

  // -----------------------------------------------------------------
  // 10. Finalize Case Twin
  // -----------------------------------------------------------------
  const finalPatch: Record<string, unknown> = {
    status,
    resolution_status: resolutionStatus,
    escalation_score: escalationScore,
    escalation_reasons: escalationScore != null
      ? (await lastEscalationReasons(db, caseUuid))
      : [],
    verification_result: verification ?? {},
    recommended_action: recommendedAction,
    agent_notes: `Handled by ${routed.specialist} agent; response sent to customer.`,
  };
  await updateCase(db, caseUuid, finalPatch);

  if (status === "escalated") {
    await emitAnalytics(db, req.customerId, caseUuid, "case_escalated", {
      intent: routed.intent, score: escalationScore,
    });
  }
  await emitCaseEvent(db, caseUuid, "resolution", status === "resolved" ? "Case Resolved" : "Escalation", status === "resolved" ? "ok" : "warn", {
    status, resolution_status: resolutionStatus,
  });

  // Incident detection
  await detectAndRecordIncident(db, caseUuid, symptoms, rootCause);
  await emitAnalytics(db, req.customerId, caseUuid, "case_opened", {
    intent: routed.intent, priority: routed.priority,
  });

  const { data: finalCase } = await db.from("resolveai_cases").select("*").eq("id", caseUuid).single();
  return {
    caseUuid,
    caseId,
    conversationUuid: convoUuid,
    response,
    status,
    resolutionStatus,
    intent: routed.intent,
    specialist: routed.specialist,
    escalationScore,
    snapshot: finalCase as Record<string, unknown>,
  };
}


async function lastEscalationReasons(db: SupabaseClient, caseUuid: string): Promise<unknown[]> {
  const { data } = await db.from("resolveai_escalations").select("reasons").eq("case_id", caseUuid).order("created_at", { ascending: false }).limit(1);
  return data && data.length > 0 ? ((data[0] as { reasons: unknown[] }).reasons ?? []) : [];
}

async function recordEscalation(
  db: SupabaseClient,
  caseUuid: string,
  esc: { score: number; reasons: string[]; recommendedQueue: string; priority: string },
  contradictions: Contradiction[],
  data: {
    caseId: string; customer: Record<string, unknown>; message: string; intent: string;
    evidence: EvidenceItem[]; hypotheses: Hypothesis[]; rootCause: string | null;
    rootConfidence: number | null; gates: Record<string, unknown>;
    recommendedAction: Record<string, unknown>;
    tickets: unknown[] | null; orders: unknown[] | null; payments: unknown[] | null;
    sentiment: string; urgency: string; conversation: unknown;
    circuitBreaker?: Record<string, unknown>;
  },
): Promise<void> {
  const passport = {
    case_id: data.caseId,
    customer_profile: {
      name: data.customer.name, tier: data.customer.tier,
      customer_code: data.customer.customer_code, lifetime_value: data.customer.lifetime_value,
    },
    original_complaint: data.message,
    conversation_summary: data.message,
    understanding: { intent: data.intent, urgency: data.urgency, sentiment: data.sentiment },
    orders: (data.orders ?? []).map((o) => (o as Record<string, unknown>).order_id),
    transactions: (data.payments ?? []).map((p) => (p as Record<string, unknown>).txn_id),
    ticket_history: (data.tickets ?? []).map((t) => (t as Record<string, unknown>).ticket_id),
    evidence: data.evidence,
    hypotheses: data.hypotheses,
    root_cause: data.rootCause,
    root_cause_confidence: data.rootConfidence,
    contradictions,
    four_gates: data.gates,
    actions_attempted: [],
    circuit_breaker: data.circuitBreaker ?? null,
    escalation_score: esc.score,
    escalation_reason: esc.reasons,
    recommended_next_action: data.recommendedAction,
  };
  await db.from("resolveai_escalations").insert({
    case_id: caseUuid,
    score: esc.score,
    reasons: esc.reasons,
    recommended_queue: esc.recommendedQueue,
    priority: esc.priority,
    passport,
    status: "open",
  });
  await updateCase(db, caseUuid, {
    status: "escalated",
    escalation_score: esc.score,
    escalation_reasons: esc.reasons,
    resolution_status: "ESCALATED",
    resolution_passport: passport,
  });
  await emitAudit(db, caseUuid, "system", "supervisor", "escalate_case", {
    input: { score: esc.score },
    decision: { escalated: true, recommended_queue: esc.recommendedQueue },
    result: { passport_generated: true },
  });
}

async function recordIncidentAndAudit(
  db: SupabaseClient,
  caseUuid: string,
  symptoms: string[],
  rootCause: string | null,
  audit: Record<string, unknown>,
): Promise<void> {
  await emitAudit(db, caseUuid, String(audit.actor), String(audit.agent), String(audit.action), {
    input: audit.input as Record<string, unknown> | undefined,
    decision: audit.decision as Record<string, unknown> | undefined,
    policy: audit.policy as Record<string, unknown> | undefined,
    authority: audit.authority as Record<string, unknown> | undefined,
    risk: audit.risk as Record<string, unknown> | undefined,
    result: audit.result as Record<string, unknown> | undefined,
    verification: audit.verification as Record<string, unknown> | undefined,
  });
}

// --- _shared/llm.ts ---
// =====================================================================
// ResolveAI — LLM module (DeepSeek V4 Flash · OpenAI Chat Completions)
// All calls are structured JSON extractions. Every call can fail safely:
// callers MUST fall back to the deterministic engine. The LLM only
// proposes understanding/hypotheses/response text — it never executes
// sensitive actions.
// =====================================================================

const AI_API_TOKEN = Deno.env.get("AI_API_TOKEN_774223bb88c5");
const AI_BASE = "https://api.enter.pro/code/api/v1/ai/chat/completions";
const ENTER_PROJECT_ID = "774223bb88c54f7c9c0176a4946bc05f";
const MODEL = "deepseek/deepseek-v4-flash";

const TIMEOUT_MS = 20000;

async function chatJSON(
  system: string,
  user: string,
  maxTokens = 900,
): Promise<unknown | null> {
  if (!AI_API_TOKEN) {
    console.warn("llm: AI_API_TOKEN missing — using deterministic fallback");
    return null;
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  try {
    const res = await fetch(AI_BASE, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${AI_API_TOKEN}`,
        "Content-Type": "application/json",
        "X-Enter-Project-ID": ENTER_PROJECT_ID,
        "X-Session-ID": crypto.randomUUID(),
      },
      body: JSON.stringify({
        model: MODEL,
        messages: [
          { role: "system", content: system },
          { role: "user", content: user },
        ],
        stream: false,
        temperature: 0,
        max_tokens: maxTokens,
      }),
      signal: controller.signal,
    });

    if (!res.ok) {
      console.warn(`llm: upstream ${res.status} ${await res.text()}`);
      return null;
    }
    const data = await res.json();
    const content: string | undefined = data.choices?.[0]?.message?.content;
    if (!content) return null;

    const cleaned = content
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```$/, "")
      .trim();
    return JSON.parse(cleaned);
  } catch (err) {
    console.warn(`llm: call failed — ${err instanceof Error ? err.message : String(err)}`);
    return null;
  } finally {
    clearTimeout(timer);
  }
}

function pick<T>(value: unknown, keys: string[], fallback: T): T {
  if (value && typeof value === "object") {
    const obj = value as Record<string, unknown>;
    for (const k of keys) {
      if (obj[k] != null) return obj[k] as T;
    }
  }
  return fallback;
}

const INTENTS = new Set(["billing", "order", "technical", "account"]);
const URGENCIES = new Set(["low", "medium", "high"]);
const SENTIMENTS = new Set(["positive", "neutral", "negative"]);

const UNDERSTAND_SYSTEM = [
  "You are the understanding layer of an autonomous customer-support system.",
  "Return STRICT JSON only (no markdown) with this exact shape:",
  '{"intent":"billing|order|technical|account","sub_intents":["..."],"urgency":"low|medium|high","sentiment":"positive|neutral|negative","sentimentScore":0..1,"priority":"P1|P2|P3|P4","confidence":0..1,"routingReason":"short phrase"}',
  "Base everything on the customer message and context provided.",
].join(" ");

export async function llmUnderstand(
  message: string,
  customerContext: string,
): Promise<Partial<Understanding> | null> {
  const userPrompt = [
    "Customer message:",
    '"""' + message + '"""',
    "",
    "Customer context:",
    customerContext,
  ].join("\n");
  const out = await chatJSON(UNDERSTAND_SYSTEM, userPrompt);
  if (!out || typeof out !== "object") return null;
  const obj = out as Record<string, unknown>;
  const intent = pick<string>(obj, ["intent"], "order");
  const urgency = pick<string>(obj, ["urgency"], "medium");
  const sentiment = pick<string>(obj, ["sentiment"], "neutral");
  return {
    intent: INTENTS.has(intent) ? intent : "order",
    subIntents: Array.isArray(obj.sub_intents)
      ? (obj.sub_intents as string[]).slice(0, 4)
      : [],
    urgency: URGENCIES.has(urgency) ? (urgency as Understanding["urgency"]) : "medium",
    sentiment: SENTIMENTS.has(sentiment)
      ? (sentiment as Understanding["sentiment"])
      : "neutral",
    sentimentScore: typeof obj.sentimentScore === "number"
      ? Math.min(1, Math.max(0, obj.sentimentScore))
      : 0.5,
    priority: /^P[1-4]$/.test(pick<string>(obj, ["priority"], "P3"))
      ? pick<string>(obj, ["priority"], "P3")
      : "P3",
    confidence: typeof obj.confidence === "number"
      ? Math.min(0.99, Math.max(0.3, obj.confidence))
      : 0.7,
    routingReason: pick<string>(obj, ["routingReason"], "Specialist match"),
  };
}

export interface HypothesisLLM {
  hypotheses: { title: string; reasoning: string; confidence: number }[];
  root_cause: string;
}

const HYPOTHESIS_SYSTEM = [
  "You are the root-cause analysis layer of an autonomous customer-support system.",
  "Return STRICT JSON only (no markdown) with this exact shape:",
  '{"hypotheses":[{"title":"...","reasoning":"...","confidence":0..1}],"root_cause":"single concise root-cause statement"}',
  "Generate 2-4 ranked hypotheses. Distinguish FACTS (from evidence) from INFERENCES in your reasoning. Never invent facts.",
].join(" ");

export async function llmHypothesize(
  message: string,
  evidenceSummary: string,
): Promise<HypothesisLLM | null> {
  const userPrompt = [
    "Customer complaint:",
    '"""' + message + '"""',
    "",
    "Collected evidence:",
    evidenceSummary,
  ].join("\n");
  const out = await chatJSON(HYPOTHESIS_SYSTEM, userPrompt, 1200);
  if (!out || typeof out !== "object") return null;
  const obj = out as Record<string, unknown>;
  const hyps = Array.isArray(obj.hypotheses) ? (obj.hypotheses as HypothesisLLM["hypotheses"]) : [];
  return {
    hypotheses: hyps.slice(0, 4).map((h) => ({
      title: String(h.title ?? "Hypothesis"),
      reasoning: String(h.reasoning ?? ""),
      confidence: typeof h.confidence === "number" ? Math.min(0.99, Math.max(0, h.confidence)) : 0.5,
    })),
    root_cause: String(obj.root_cause ?? "Unable to determine root cause"),
  };
}

const RESPOND_SYSTEM = [
  "You write the customer-facing reply for an autonomous customer-support platform.",
  'Return STRICT JSON only: {"reply":"<text>"}',
  "Be warm, professional, concise (4-7 sentences max). Ground every claim strictly in the context provided.",
  "If the case was escalated, say a specialist team is taking over and make no promise of a refund.",
  "If a refund was issued and verified, state the amount and expected timeline.",
  "Never invent details not in the context.",
].join(" ");

export async function llmRespond(
  customerName: string,
  context: string,
): Promise<string | null> {
  const userPrompt = ["Customer:", customerName, "", "Case context:", context].join("\n");
  const out = await chatJSON(RESPOND_SYSTEM, userPrompt, 600);
  if (!out || typeof out !== "object") return null;
  return pick<string>(out, ["reply"], "");
}


// --- router ---
// =====================================================================
// resolveai — ROUTER SOURCE (source of truth, not deployed directly)
//
// Single backend function exposing all ResolveAI endpoints via a route
// field. Routes:
//   POST chat        — customer message → full lifecycle
//   POST actions     — gated deterministic action tools
//   POST escalate    — manual escalation + Resolution Passport
//   GET  analytics   — operational & CX KPIs (server-computed)
//   GET  incidents   — incidents + fingerprints + linked cases
//   POST bootstrap   — create demo auth accounts (idempotent)
//   POST selfcheck   — integration harness for demo tracks A/B/C
//
// scripts/bundle-resolveai.mjs inlines ./_shared/* into index.ts (the
// deployable bundle). Edit this file and _shared/, then run the bundler.
// =====================================================================

const BOOT_SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
const BOOT_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY") ?? "";

async function handleChat(token: string | null, body: Record<string, unknown>): Promise<Response> {
  const caller = await resolveCaller(token);
  const message = String(body.message ?? "").trim();
  if (!message) return jsonResponse({ error: "message_required" }, 400);

  let customerId: string | null = null;
  if (body.case_uuid) {
    // Continue path: the customer is the one who owns the existing case.
    // Staff may continue any case; customers only their own.
    const { data: cRow } = await db
      .from("resolveai_cases")
      .select("customer_id")
      .eq("id", String(body.case_uuid))
      .maybeSingle();
    if (!cRow) return jsonResponse({ error: "case_not_found" }, 404);
    const targetCustomer = String((cRow as { customer_id: string }).customer_id);
    const isStaff = Boolean(caller.staffRole);
    const ownsCustomer = caller.customerId === targetCustomer;
    if (!isStaff && !ownsCustomer) {
      return jsonResponse({ error: "unauthorized_customer" }, 403);
    }
    customerId = targetCustomer;
  } else if (body.customer_id) {
    const isStaff = Boolean(caller.staffRole);
    const ownsCustomer = caller.customerId === String(body.customer_id);
    if (isStaff || ownsCustomer) {
      customerId = String(body.customer_id);
    } else {
      return jsonResponse({ error: "unauthorized_customer" }, 403);
    }
  } else {
    customerId = caller.customerId;
  }
  if (!customerId) {
    return jsonResponse(
      { error: "customer_required", detail: "Log in as a customer or pass customer_id (staff)." },
      400,
    );
  }

  const result = await runLifecycle(db, {
    customerId,
    message,
    staffRole: caller.staffRole,
    actor: caller.actor,
    fast: body.fast === true,
    skipLlm: body.skipLlm === true,
    earlyReturn: body.start_only === true,
    existingCaseUuid: body.case_uuid ? String(body.case_uuid) : undefined,
    existingConversationUuid: body.conversation_id ? String(body.conversation_id) : null,
  });

  return jsonResponse({
    ok: true,
    case_id: result.caseId,
    case_uuid: result.caseUuid,
    conversation_id: result.conversationUuid,
    intent: result.intent,
    specialist: result.specialist,
    status: result.status,
    resolution_status: result.resolutionStatus,
    escalation_score: result.escalationScore,
    reply: result.response,
    snapshot: result.snapshot,
  });
}

async function handleActions(token: string | null, body: Record<string, unknown>): Promise<Response> {
  const caller = await resolveCaller(token);
  if (!caller.staffRole) {
    return jsonResponse({
      error: "forbidden",
      detail: "Staff role required",
      debug: { userId: caller.userId, staffRole: caller.staffRole, customerId: caller.customerId, actor: caller.actor },
    }, 403);
  }

  const action = String(body.action ?? "");
  const caseUuid = String(body.case_id ?? "");
  if (!action || !caseUuid) {
    return jsonResponse({ error: "action_and_case_required" }, 400);
  }

  const { data: caseRow } = await db
    .from("resolveai_cases")
    .select("*")
    .eq("id", caseUuid)
    .maybeSingle();
  if (!caseRow) return jsonResponse({ error: "case_not_found" }, 404);
  const cs = caseRow as Record<string, unknown>;

  const { data: customer } = await db
    .from("resolveai_customers")
    .select("*")
    .eq("id", String(cs.customer_id))
    .maybeSingle();
  const cust = customer as Record<string, unknown> | null;

  let paymentUuid: string | null = null;
  let amount = typeof body.amount === "number" ? body.amount : undefined;
  if (action === "issue_refund") {
    const query = body.payment_id
      ? { id: String(body.payment_id) }
      : body.payment_txn
        ? { txn_id: String(body.payment_txn) }
        : null;
    if (!query) return jsonResponse({ error: "payment_required" }, 400);
    const { data: payment } = await db
      .from("resolveai_payments")
      .select("*")
      .match(query)
      .maybeSingle();
    if (!payment) return jsonResponse({ error: "payment_not_found" }, 404);
    paymentUuid = (payment as { id: string }).id;
    amount = amount ?? Number((payment as { amount: number }).amount);
  }

  const { data: policies } = await db.from("resolveai_policies").select("*");
  const policyRows = (policies ?? []) as Record<string, unknown>[];
  const policyEval = evaluatePolicy(policyRows as never, action, {
    twoSuccessfulPaymentsSameOrder: true,
    amount: amount ?? 0,
    amountWithinAuthority: amount != null ? amount <= (AUTHORITY_LIMITS[caller.staffRole] ?? 1000) : true,
    orderPending: false,
    within30Days: true,
    deliveryEvidenceComplete: true,
    noContradiction: !Boolean(cs.contradiction_detected),
    identityVerified: true,
    defectConfirmed: true,
    fraudRisk: "low",
  });

  const gateInputs: GateInputs = {
    evidence: (cs.evidence as unknown[]) ?? [],
    action,
    amount: amount ?? null,
    customerTier: String(cust?.tier ?? "standard"),
    staffRole: caller.staffRole,
    policyAllowed: policyEval.allowed,
    policyId: policyEval.policyId,
    contradictions: cs.contradiction_detected ? 1 : 0,
    repeatContacts: Number((cs.customer_history as Record<string, unknown>)?.repeat_contacts ?? 0),
    sentiment: String(cs.sentiment ?? "neutral"),
    uncertainty: 0.2,
    highValueCustomer: Number(cust?.lifetime_value ?? 0) >= 30000,
    hasDuplicates: Boolean((cs.evidence as unknown[])?.some?.((e) => (e as { type?: string }).type === "duplicate_payment")),
    actionFailures: ((cs.action_history as unknown[]) ?? []).filter((a) => (a as { status?: string }).status === "failed").length,
  };
  const gates = evaluateAllGates(gateInputs);

  const humanDecision = body.human_decision ? String(body.human_decision) : null;

  if (!gates.canAutoResolve) {
    // ---- Human approval / override path ----
    const staffLimit = amount != null ? (AUTHORITY_LIMITS[caller.staffRole] ?? 0) : 0;
    const approvableByHuman =
      policyEval.allowed &&
      !Boolean(cs.contradiction_detected) &&
      amount != null &&
      amount <= staffLimit &&
      gates.gates.risk.status !== "BLOCK";

    if (humanDecision === "approve") {
      if (!approvableByHuman) {
        await emitAudit(db, caseUuid, caller.actor, "supervisor", `reject_${action}`, {
          input: { human_decision: "approve", amount },
          decision: { allowed: false, reason: "requested override exceeds available authority or blocked by risk/contradiction" },
          authority: gates.gates.authority,
          risk: gates.gates.risk,
        });
        return jsonResponse({
          ok: false,
          action,
          blocked: true,
          detail: "Approval denied — override exceeds the acting role's authority or is blocked by risk/contradiction.",
        }, 403);
      }
      // Override proceeds; audit records the human decision before execution.
      await emitAudit(db, caseUuid, caller.actor, "supervisor", `approve_${action}`, {
        input: { amount },
        decision: { human_approval: true, gates: gates.gates, allowed: true },
        authority: gates.gates.authority,
        risk: gates.gates.risk,
      });
    } else if (humanDecision === "reject") {
      await emitAudit(db, caseUuid, caller.actor, "supervisor", `reject_${action}`, {
        input: { amount },
        decision: { human_decision: "reject", allowed: false },
        authority: gates.gates.authority,
        risk: gates.gates.risk,
      });
      return jsonResponse({ ok: true, action, decision: "rejected", detail: "Action rejected by human reviewer." });
    } else {
      // No decision yet → return an approval recommendation for the UI.
      return jsonResponse({
        ok: false,
        action,
        requires_human_approval: true,
        approvable_by_human: approvableByHuman,
        gates: gates.gates,
        policy: { policy_id: policyEval.policyId, allowed: policyEval.allowed },
        authority: gates.gates.authority,
        risk: gates.gates.risk,
        amount,
        detail: approvableByHuman
          ? "Autonomous gates did not pass, but a human reviewer with sufficient authority can approve this action."
          : "Autonomous gates did not pass and this action is not approvable by the acting role.",
      }, 202);
    }
  }

  let result: { action: unknown; verification: unknown } | null = null;
  if (action === "issue_refund") {
    result = await executeRefund(db, {
      caseUuid,
      caseId: String(cs.case_id),
      customerId: String(cs.customer_id),
      paymentUuid: paymentUuid!,
      amount: amount!,
      agentKey: "billing",
    });
  } else if (action === "update_ticket") {
    const res = await executeUpdateTicket(db, {
      caseUuid,
      customerId: String(cs.customer_id),
      intent: String(cs.intent ?? "order"),
      note: body.note ? String(body.note) : "Specialist action executed",
      agentKey: caller.staffRole,
    });
    result = { action: res, verification: { overall: "passed", checks: [], detail: res.detail } };
  } else if (action === "send_message") {
    const res = await executeSendMessage(db, {
      conversationUuid: cs.conversation_id ? String(cs.conversation_id) : null,
      content: body.content ? String(body.content) : "Your case has been updated by our team.",
      agentKey: caller.staffRole,
    });
    result = { action: res, verification: { overall: "passed", checks: [], detail: res.detail } };
  } else {
    return jsonResponse({ error: "unsupported_action" }, 400);
  }

  const actionRes = result.action as { status: string; action: string; output: Record<string, unknown>; detail: string; error?: string };
  const actionUuid = await recordAgentAction(
    db, caseUuid, "billing", action, actionRes.status === "succeeded" ? "succeeded" : "failed",
    { ...body }, actionRes.output, actionRes.error,
  );
  await recordVerification(db, actionUuid, caseUuid, result.verification as never);
  await emitAudit(db, caseUuid, caller.actor, "billing", action, {
    input: body,
    policy: { policy_id: policyEval.policyId, allowed: policyEval.allowed },
    authority: gates.gates.authority,
    risk: gates.gates.risk,
    result: actionRes,
    verification: result.verification,
  });

  return jsonResponse({ ok: true, action, result, verification: result.verification });
}

async function handleEscalate(token: string | null, body: Record<string, unknown>): Promise<Response> {
  const caller = await resolveCaller(token);
  if (!caller.staffRole) {
    return jsonResponse({ error: "forbidden", detail: "Staff role required" }, 403);
  }
  if (!body.case_id) return jsonResponse({ error: "case_id_required" }, 400);
  const caseUuid = String(body.case_id);

  const { data: caseRow } = await db.from("resolveai_cases").select("*").eq("id", caseUuid).maybeSingle();
  if (!caseRow) return jsonResponse({ error: "case_not_found" }, 404);
  const cs = caseRow as Record<string, unknown>;

  const { data: customer } = await db.from("resolveai_customers").select("*").eq("id", String(cs.customer_id)).maybeSingle();
  const cust = customer as Record<string, unknown> | null;

  const esc = computeEscalation({
    intent: String(cs.intent ?? "order"),
    caseComplexity: 0.6,
    repeatContacts: Number((cs.customer_history as Record<string, unknown>)?.repeat_contacts ?? 0),
    sentiment: String(cs.sentiment ?? "neutral"),
    financialImpact: Number((cs.recommended_action as Record<string, unknown>)?.amount ?? 0),
    policyUncertainty: Boolean(cs.policy_result && !(cs.policy_result as Record<string, unknown>).allowed),
    conflictingEvidence: Boolean(cs.contradiction_detected),
    aiConfidence: Number(cs.root_cause_confidence ?? cs.routing_confidence ?? 0.5),
    actionFailures: ((cs.action_history as unknown[]) ?? []).filter((a) => (a as { status?: string }).status === "failed").length,
    slaRisk: cs.sla_deadline ? new Date(String(cs.sla_deadline)).getTime() < Date.now() + 3600_000 : false,
  });

  const ctx = {
    caseId: String(cs.case_id),
    customer: {
      id: String(cs.customer_id),
      name: String(cust?.name ?? "Customer"),
      tier: String(cust?.tier ?? "standard"),
      lifetimeValue: Number(cust?.lifetime_value ?? 0),
      churnRisk: Number(cust?.churn_risk ?? 0),
      repeatContacts: Number((cs.customer_history as Record<string, unknown>)?.repeat_contacts ?? 0),
      priorRefunds: Number(cust?.refunds_count ?? 0),
    },
    orderIds: (cs.order_ids as string[]) ?? [],
    transactionIds: (cs.transaction_ids as string[]) ?? [],
    ticketIds: (cs.ticket_ids as string[]) ?? [],
    message: String(cs.message_text ?? ""),
    intent: String(cs.intent ?? "order"),
    subIntents: (cs.sub_intents as string[]) ?? [],
    urgency: String(cs.urgency ?? "medium"),
    sentiment: String(cs.sentiment ?? "neutral"),
    priority: String(cs.priority ?? "P3"),
    specialist: String(cs.specialist ?? "order"),
    routingReason: String(cs.routing_reason ?? ""),
    routingConfidence: Number(cs.routing_confidence ?? 0.6),
    evidence: (cs.evidence as unknown[]) ?? [],
    hypotheses: (cs.hypotheses as unknown[]) ?? [],
    rootCause: cs.root_cause ? String(cs.root_cause) : null,
    rootCauseConfidence: cs.root_cause_confidence != null ? Number(cs.root_cause_confidence) : null,
    contradictions: (cs.contradictions as unknown[]) ?? [],
    gates: (cs.gates as Record<string, unknown>) ?? {},
    policy: (cs.policy_result as Record<string, unknown>) ?? {},
    authority: (cs.authority_result as Record<string, unknown>) ?? {},
    risk: (cs.risk_result as Record<string, unknown>) ?? {},
    actionHistory: (cs.action_history as Record<string, unknown>[]) ?? [],
    recommendedAction: (cs.recommended_action as Record<string, unknown>) ?? {},
    escalation: esc,
    verification: cs.verification_result ? (cs.verification_result as { overall: string; checks: unknown[] }) : null,
    resolved: false,
    resolutionStatus: "ESCALATED",
    passport: {},
  } as CaseContext;

  const passport = buildPassport(ctx);
  const { error: escErr } = await db.from("resolveai_escalations").insert({
    case_id: caseUuid,
    score: esc.score,
    reasons: esc.reasons,
    recommended_queue: esc.recommendedQueue,
    priority: esc.priority,
    passport,
    status: "open",
  });
  if (escErr) throw escErr;

  await updateCase(db, caseUuid, {
    status: "escalated",
    escalation_score: esc.score,
    escalation_reasons: esc.reasons,
    resolution_status: "ESCALATED",
    resolution_passport: passport,
  });
  await emitAudit(db, caseUuid, caller.actor, "supervisor", "escalate_case", {
    input: { manual: true },
    decision: { escalated: true, score: esc.score, queue: esc.recommendedQueue },
  });
  await emitAnalytics(db, String(cs.customer_id), caseUuid, "case_escalated", {
    intent: String(cs.intent),
    score: esc.score,
    manual: true,
  });

  return jsonResponse({ ok: true, case_id: cs.case_id, score: esc.score, reasons: esc.reasons, passport });
}

async function handleAnalytics(token: string | null): Promise<Response> {
  const caller = await resolveCaller(token);
  if (!caller.staffRole) return jsonResponse({ error: "forbidden", detail: "Staff role required" }, 403);
  const { data, error } = await db.rpc("resolveai_analytics_snapshot");
  if (error) throw error;
  return jsonResponse({ ok: true, analytics: data });
}

async function handleIncidents(token: string | null): Promise<Response> {
  const caller = await resolveCaller(token);
  if (!caller.staffRole) return jsonResponse({ error: "forbidden", detail: "Staff role required" }, 403);
  const { data: counts } = await db.from("resolveai_incident_cases").select("incident_id, count:case_id");
  if (counts) {
    for (const row of counts as { incident_id: string; count: number }[]) {
      await db
        .from("resolveai_incidents")
        .update({ affected_case_count: row.count, updated_at: new Date().toISOString() })
        .eq("id", row.incident_id);
    }
  }
  const { data: incidents } = await db.from("resolveai_incidents").select("*").order("first_detected_at", { ascending: false });
  const { data: links } = await db.from("resolveai_incident_cases").select("incident_id, case_id");
  const { data: fingerprints } = await db.from("resolveai_failure_fingerprints").select("*").order("frequency", { ascending: false });
  const byIncident: Record<string, string[]> = {};
  for (const link of (links ?? []) as { incident_id: string; case_id: string }[]) {
    (byIncident[link.incident_id] ??= []).push(link.case_id);
  }
  return jsonResponse({
    ok: true,
    incidents: (incidents ?? []).map((i) => ({
      ...(i as Record<string, unknown>),
      linked_case_uuids: byIncident[(i as { id: string }).id] ?? [],
    })),
    fingerprints: fingerprints ?? [],
  });
}

